def guard_problem(doc, a, b):
    if (a, b) == ("draft", "published") and not doc["title"]:
        return "title is empty"
    return None

class Doc:
    def __init__(self, title):
        self.title = title
        self.status = "draft"
    def move(self, target):
        if target not in TRANSITIONS[self.status]:
            return f"REFUSED (no such transition): {self.status} -> {target}"
        problem = guard_problem({"title": self.title}, self.status, target)
        if problem:
            return f"REFUSED (guard): {problem}"
        self.status = target
        return f"ok: now {self.status}"

