class Editor:
    def __init__(self):
        self.states = [""]
        self.pos = 0
        self.saved_pos = 0
    @property
    def text(self):
        return self.states[self.pos]
    def type(self, s):
        self.states = self.states[:self.pos + 1] + [self.text + s]
        self.pos += 1
    def undo(self):
        self.pos -= 1
    def save(self):
        self.saved_pos = self.pos
    def is_modified(self):
        return self.pos != self.saved_pos

