from collections import deque

class Editor:
    def __init__(self, limit):
        self.text = ""
        self.undo_stack = deque(maxlen=limit)
    def type(self, s):
        self.undo_stack.append(self.text)
        self.text += s
    def undo(self):
        if not self.undo_stack:
            return "nothing to undo"
        self.text = self.undo_stack.pop()
        return self.text

